{"type":"item.completed","item":{"id":"item_1","type":"agent_message","text":"{\"tool\":\"sql_query\",\"arguments\":{\"company_name\":\"CLOSE_fin_06\",\"table_name\":\"ledger\",\"query\":\"WITH ranked AS (SELECT kind,event_key,invoice_id,vendor,business_date,recorded_at,revision,status,amount_minor,currency,due_date,discount_until,terms_code,discount_bps,fx_num,fx_den,ROW_NUMBER() OVER (PARTITION BY kind,event_key ORDER BY revision DESC) AS rn FROM ledger WHERE business_date <= '2026-10-23' AND datetime(recorded_at) <= datetime('2026-10-24T12:00:00')), active AS (SELECT kind,event_key,invoice_id,vendor,business_date,status,amount_minor,currency,due_date,discount_until,terms_code,discount_bps,fx_num,fx_den FROM ranked WHERE rn=1 AND status <> 'void'), components AS (SELECT i.event_key,i.business_date,i.currency,i.amount_minor,i.discount_until,i.terms_code,COALESCE((SELECT SUM(p.amount_minor) FROM active p WHERE p.kind='payment' AND p.invoice_id=i.event_key),0) AS payments,COALESCE((SELECT SUM(c.amount_minor) FROM active c WHERE c.kind='credit' AND c.invoice_id=i.event_key),0) AS credits,COALESCE((SELECT SUM(h.amount_minor) FROM active h WHERE h.kind='hold' AND h.status='active' AND h.invoice_id=i.event_key),0) AS holds,(SELECT t.discount_bps FROM active t WHERE t.kind='terms' AND t.terms_code=i.terms_code AND t.business_date<=i.business_date ORDER BY t.business_date DESC LIMIT 1) AS discount_bps,(SELECT f.fx_num FROM active f WHERE f.kind='fx' AND f.currency=i.currency AND f.business_date<=i.business_date ORDER BY f.business_date DESC LIMIT 1) AS fx_num,(SELECT f.fx_den FROM active f WHERE f.kind='fx' AND f.currency=i.currency AND f.business_date<=i.business_date ORDER BY f.business_date DESC LIMIT 1) AS fx_den FROM active i WHERE i.kind='invoice' AND i.vendor='BLUE' AND i.due_date<='2026-10-30') SELECT event_key,business_date,currency,amount_minor,payments,credits,holds,MAX(0,MAX(0,amount_minor-payments-credits)-holds) AS unheld,discount_until,terms_code,discount_bps,fx_num,fx_den FROM components WHERE 1=1 ORDER BY event_key\"}}"}}
